import type { KatexOptions } from 'katex';

import type katexDefault from 'katex';

type Katex = typeof katexDefault;

export interface RenderResult {
  /** KaTeX HTML + MathML markup (safe: generated by KaTeX with `trust: false`). */
  html: string | null;
  /** Human-readable error for invalid LaTeX. */
  error: string | null;
}

/**
 * Security-hardened KaTeX options (ADR-0005):
 * no \href/\url/\includegraphics/\htmlClass, bounded macro expansion and sizes.
 */
export const SAFE_KATEX_OPTIONS: KatexOptions = {
  throwOnError: true,
  trust: false,
  strict: 'ignore',
  output: 'htmlAndMathml', // MathML is read by screen readers (MATH-037)
  maxExpand: 500,
  maxSize: 50,
};

let katexPromise: Promise<Katex> | null = null;
let katexInstance: Katex | null = null;

/** Loads KaTeX on demand (MATH-045): documents without math never download it. */
export function loadKatex(): Promise<Katex> {
  katexPromise ??= import('katex').then((mod) => {
    katexInstance = mod.default;
    return mod.default;
  });
  return katexPromise;
}

export function isKatexLoaded(): boolean {
  return katexInstance !== null;
}

const MAX_CACHE = 500;
const cache = new Map<string, RenderResult>();

/** Renders LaTeX synchronously (KaTeX must be loaded). Results are cached by source. */
export function renderLatex(latex: string, displayMode: boolean): RenderResult {
  const katex = katexInstance;
  if (!katex) return { html: null, error: null };
  const key = `${displayMode ? 'D' : 'I'}:${latex}`;
  const hit = cache.get(key);
  if (hit) return hit;
  let result: RenderResult;
  if (latex.trim() === '') {
    result = { html: null, error: null };
  } else {
    try {
      result = {
        html: katex.renderToString(latex, { ...SAFE_KATEX_OPTIONS, displayMode }),
        error: null,
      };
    } catch (err) {
      const message =
        err instanceof Error ? err.message.replace(/^KaTeX parse error:\s*/, '') : String(err);
      result = { html: null, error: message };
    }
  }
  if (cache.size >= MAX_CACHE) {
    const oldest = cache.keys().next().value;
    if (oldest !== undefined) cache.delete(oldest);
  }
  cache.set(key, result);
  return result;
}

/** Validates LaTeX without rendering to the document (MATH-044). */
export async function validateLatex(latex: string): Promise<string | null> {
  await loadKatex();
  return renderLatex(latex, false).error;
}
